/**
 * @fileoverview Builds the button, axis, rumble, and LED configurations of the controllers from
 * first_ds_hids.json.
 *
 * first_ds_hids.json is what robotpy uses to generate its controller classes (XboxController,
 * DualSenseController, etc). It is generated by python_tools/generate_gamepads.py, which gets the
 * file for the version of robotpy in packaging/cacheRequirements.txt. Don't edit it by hand.
 *
 * The key of each button and axis is its index, which is what is saved in blocks. The same index
 * is the same physical position on every controller (index 0 is the face button closest to the
 * user, which is A on an XBOX controller and Cross on a PlayStation controller), so changing the
 * type of a port keeps the blocks working. The names shown to the user are the names in the json.
 */
import * as Generic from './gamepad_generic';
import hidsJson from './first_ds_hids.json';

type Hid = {
  ClassName: string;
  axes: Record<string, number>;
  buttons: Record<string, number>;
  supports: {
    rumble: boolean;
    triggerRumble: boolean;
    monoLed: boolean;
    rgbLed: boolean;
  };
};

const HIDS = hidsJson as unknown as Hid[];

function getHid(className: string): Hid {
  const hid = HIDS.find((h) => h.ClassName === className);
  if (!hid) {
    throw new Error('first_ds_hids.json has no controller named ' + className);
  }
  return hid;
}

/** Splits a name from the json (such as leftStick, L1, PS, or CStickX) into its words. */
function splitName(name: string): string[] {
  return name
      .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
      .replace(/([A-Z])([A-Z][a-z])/g, '$1 $2')
      .split(' ');
}

/** Converts a name from the json to the form used in the names of wpilib methods. */
function toMethodPart(name: string): string {
  return splitName(name).join('_').toLowerCase();
}

/** Converts a name from the json to the name shown to the user. */
function toDisplayName(name: string): string {
  return splitName(name).map((word) => word.charAt(0).toUpperCase() + word.slice(1)).join(' ');
}

/** Makes a config from the buttons or axes in the json, in order of their indexes. */
function makeConfig(
    indexes: Record<string, number>, toMethod: (name: string) => string): Map<string, Generic.ConfigEntry> {
  return new Map(Object.entries(indexes)
      .sort((a, b) => a[1] - b[1])
      .map(([name, index]) => [String(index), {
        display: () => toDisplayName(name),
        method: toMethod(name),
      }]));
}

/** Returns the button configuration for the controller with the given ClassName. */
export function getButtonConfig(className: string): Map<string, Generic.ConfigEntry> {
  return makeConfig(getHid(className).buttons, (name) => 'get_' + toMethodPart(name) + '_button');
}

/** Returns the axis configuration for the controller with the given ClassName. */
export function getAxisConfig(className: string): Map<string, Generic.ConfigEntry> {
  return makeConfig(getHid(className).axes, (name) => 'get_' + toMethodPart(name));
}

/** Returns the rumble configuration for the controller, or null if it has no rumble motors. */
export function getRumbleConfig(className: string): Map<string, Generic.RumbleConfigEntry> | null {
  const supports = getHid(className).supports;
  if (!supports.rumble) {
    return null;
  }
  const config = new Map(Generic.getRumbleConfig());
  if (!supports.triggerRumble) {
    config.delete('TRIGGER_LEFT_RUMBLE');
    config.delete('TRIGGER_RIGHT_RUMBLE');
  }
  return config;
}

/**
 * Returns the LED configuration for the controller, or null if it has no RGB LED. (A controller
 * with only a mono LED, such as the Switch Pro, is not supported.)
 */
export function getLEDConfig(className: string): Map<string, Generic.ConfigEntry> | null {
  return getHid(className).supports.rgbLed ? Generic.getLEDConfig() : null;
}

/** Returns all four configurations for the controller with the given ClassName. */
export function forClass(className: string) {
  getHid(className); // Fail early if there is no such controller.
  return {
    getButtonConfig: () => getButtonConfig(className),
    getAxisConfig: () => getAxisConfig(className),
    getRumbleConfig: () => getRumbleConfig(className),
    getLEDConfig: () => getLEDConfig(className),
  };
}
